def unpack(be: bytes) -> int:
    """Giải mã big-endian không dấu."""
    value = 0
    for byte in be:
        value = (value << 8) | byte
    return value


def pack(value: int, size: int) -> bytes:
    """Đóng gói big-endian."""
    if not 0 <= value < (1 << (8 * size)):
        raise ValueError(f'giá trị {value} không vừa {size} byte')
    return value.to_bytes(size, 'big')


def decode_int8(raw: int) -> int | None:
    """-1..127, 0x80 là không hợp lệ (None)."""
    if raw == 0x80:
        return None
    return raw - 256 if raw >= 0x80 else raw


def decode_event(mask: int) -> set[str]:
    return {name for name, bit in EVENT_BITS.items() if mask & bit}


def encode_event(names: set[str]) -> int:
    mask = 0
    for name in names:
        mask |= EVENT_BITS[name]
    return mask
